import 'dart:convert';

import 'data.dart';

class OwnerShipsRequestsResponse {
	String? message;
	Data? data;

	OwnerShipsRequestsResponse({this.message, this.data});

	factory OwnerShipsRequestsResponse.(Map<String, dynamic> data) {
		return OwnerShipsRequestsResponse(
			message: data['message'] as String?,
			data: data['data'] == null
						? null
						: Data.(data['data'] as Map<String, dynamic>),
		);
	}



	Map<String, dynamic> () {
		return {
			'message': message,
			'data': data?.(),		};
	}

  /// `dart:convert`
  ///
  /// Parses the string and returns the resulting Json object as [OwnerShipsRequestsResponse].
	factory OwnerShipsRequestsResponse.fromJson(String data) {
		return OwnerShipsRequestsResponse.(json.decode(data) as Map<String, dynamic>);
	}
  /// `dart:convert`
  ///
  /// Converts [OwnerShipsRequestsResponse] to a JSON string.
	String toJson() => json.encode(());
}
